  if (!host || !slug || !CATALOG[slug]) { if(host) host.hidden = true; return; }
  var cat = CATALOG[slug].cat;
  // 회전 선택 — 알파벳 앞 도구에만 링크가 몰리지 않게 각 도구의 인바운드를 균등하게 만든다.
